SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.legal_claim_firm_pack_notifications(p_order uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 WITH pending AS (
   SELECT id FROM public.legal_firm_pack_orders WHERE notification_sent_at IS NULL AND notification_next_at<=now()
     AND (p_order IS NULL OR id=p_order) ORDER BY created_at LIMIT 20 FOR UPDATE SKIP LOCKED
 ), claimed AS (
   UPDATE public.legal_firm_pack_orders o SET notification_claim=gen_random_uuid(),notification_attempts=notification_attempts+1,
     notification_next_at=now()+interval '5 minutes' FROM pending WHERE o.id=pending.id RETURNING o.*
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'quantity',c.quantity,'created_at',c.created_at,
     'claim_token',c.notification_claim,'firm_name',f.firm_name)),'[]') INTO result FROM claimed c JOIN public.legal_firms f ON f.id=c.firm_id;
 RETURN result;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_claim_sales_lead(p_session_id uuid, p_previous_lead_id uuid DEFAULT NULL::uuid, p_preferred_lead_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- no_answer_four_hour_retry
DECLARE
  rep uuid := public.legal_sales_queue_rep(p_session_id);
  current_lead uuid;
  chosen uuid;
  today date := (now() AT TIME ZONE 'Australia/Sydney')::date;
BEGIN
  SELECT c.lead_id INTO current_lead FROM public.legal_sales_lead_claims c
    JOIN public.legal_client_leads l ON l.id = c.lead_id AND l.rep_id = rep
    WHERE c.session_id = p_session_id FOR UPDATE OF l;
    -- A previously reserved city may have filled up since the last request.
  IF current_lead IS NOT NULL AND NOT (SELECT public.legal_sales_queue_city_has_capacity(city) FROM public.legal_client_leads WHERE id=current_lead) THEN
    DELETE FROM public.legal_sales_lead_claims WHERE session_id=p_session_id;
    current_lead:=NULL;
  END IF;
-- A refresh resumes the current client. A repeated Next request cannot skip
  -- the client already selected by the first request.
  IF current_lead IS NOT NULL AND (
    (p_previous_lead_id IS NULL AND (p_preferred_lead_id IS NULL OR p_preferred_lead_id = current_lead))
    OR (p_previous_lead_id IS NOT NULL AND current_lead <> p_previous_lead_id)
  ) THEN
    UPDATE public.legal_sales_lead_claims SET expires_at = now() + interval '15 minutes'
      WHERE session_id = p_session_id;
    RETURN current_lead;
  END IF;

  -- Enabled callers can explicitly open a client assigned to any advisor.
  -- It still cannot take a client away from another active caller.
  IF p_preferred_lead_id IS NOT NULL THEN
    SELECT l.id INTO chosen FROM public.legal_client_leads l
    WHERE l.id = p_preferred_lead_id AND (l.rep_id = rep OR public.legal_is_admin_user() OR (l.rep_id IS NOT NULL AND public.legal_can_view_team_clients()))
      AND NOT EXISTS (SELECT 1 FROM public.legal_sales_lead_claims c
        JOIN public.legal_rep_sessions s ON s.id = c.session_id
        WHERE c.lead_id = l.id AND c.session_id <> p_session_id
          AND c.expires_at > now() AND s.ended_at IS NULL)
    FOR UPDATE OF l SKIP LOCKED;
    IF chosen IS NULL THEN RAISE EXCEPTION 'This client is unavailable or with another caller'; END IF;
    IF NOT (SELECT public.legal_sales_queue_city_has_capacity(city) FROM public.legal_client_leads WHERE id=chosen) THEN
      RAISE EXCEPTION 'Sydney calls are paused: no booking capacity is available.';
    END IF;
  END IF;

  IF current_lead IS NOT NULL THEN
    INSERT INTO public.legal_sales_session_visits(session_id, lead_id, visited_at)
      VALUES (p_session_id, current_lead, now())
      ON CONFLICT (session_id, lead_id) DO UPDATE SET visited_at = excluded.visited_at;
  END IF;
  DELETE FROM public.legal_sales_lead_claims WHERE session_id = p_session_id;

  IF p_preferred_lead_id IS NULL THEN
    SELECT l.id INTO chosen FROM public.legal_client_leads l
    LEFT JOIN LATERAL (
      SELECT count(DISTINCT coalesce(c.twilio_call_sid, c.id::text)) FILTER (
          WHERE (c.created_at AT TIME ZONE 'Australia/Sydney')::date = today) AS attempts_today,
        count(DISTINCT (c.created_at AT TIME ZONE 'Australia/Sydney')::date) AS call_days,
        (array_agg(lower(coalesce(c.call_status, '')) ORDER BY c.created_at DESC, c.id))[1] AS last_status
      FROM public.legal_call_records c WHERE c.lead_id = l.id
        AND (c.direction IS NULL OR c.direction = 'outbound')
        AND lower(coalesce(c.call_status, '')) NOT IN ('failed','canceled','cancelled','initiated','skipped')
    ) a ON true
    -- A call made before this queue/session existed still counts as worked today.
    -- Include initiated/failed/cancelled dials: moving on must not recycle them
    -- merely because a final telephony status has not arrived. Explicit redials
    -- on the current client remain available.
    LEFT JOIN LATERAL (
      SELECT max(c.created_at) AS last_dial_today
      FROM public.legal_call_records c WHERE c.lead_id = l.id
        AND (c.direction IS NULL OR c.direction = 'outbound')
        AND lower(coalesce(c.call_status, '')) <> 'skipped'
        AND (c.created_at AT TIME ZONE 'Australia/Sydney')::date = today
    ) worked ON true
    WHERE public.legal_sales_queue_city_has_capacity(l.city) AND NOT (l.status = 'callback_scheduled' AND l.callback_scheduled_at IS NOT NULL AND l.callback_scheduled_at > now())
      AND (
        lower(regexp_replace(trim(coalesce(l.first_name,'') || ' ' || coalesce(l.last_name,'')), '\s+', ' ', 'g')) IN ('peter test','peter test 2')
        OR (
          l.status NOT IN ('not_interested','booked_deposit_paid','had_convo_no_sale','did_not_qualify','cancelled','no_show','dropped')
          AND NOT EXISTS (SELECT 1 FROM public.legal_app_settings s,
            LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(s.value) = 'array' THEN s.value ELSE '[]'::jsonb END) AS cities(city_name)
            WHERE s.key = 'paused_cities' AND lower(trim(cities.city_name)) = lower(trim(l.city)))
          AND NOT EXISTS (SELECT 1 FROM public.legal_app_settings s
            WHERE s.key = 'focus_cities' AND jsonb_typeof(s.value) = 'array' AND s.value <> '[]'::jsonb
              AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(s.value) AS cities(city_name) WHERE lower(trim(cities.city_name)) = lower(trim(l.city))))
          AND (
            worked.last_dial_today IS NULL OR (l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours')
            OR (l.status = 'callback_scheduled' AND l.callback_scheduled_at > worked.last_dial_today
              AND l.callback_scheduled_at <= now())
            OR EXISTS (SELECT 1 FROM public.legal_call_records c WHERE c.lead_id = l.id
              AND c.direction = 'inbound' AND c.created_at > worked.last_dial_today)
          )
          AND ((l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours') OR a.attempts_today < CASE WHEN (l.created_at AT TIME ZONE 'Australia/Sydney')::date >= today - 6 THEN 3 ELSE 1 END)
          AND NOT (a.call_days > 21 AND (l.status = 'no_answer' OR a.last_status IN ('no-answer','no_answer','noanswer','busy','voicemail','missed')))
        )
      )
      AND NOT EXISTS (SELECT 1 FROM public.legal_sales_lead_claims c
        JOIN public.legal_rep_sessions s ON s.id = c.session_id
        WHERE c.lead_id = l.id AND c.expires_at > now() AND s.ended_at IS NULL)
      AND NOT EXISTS (SELECT 1 FROM public.legal_sales_session_visits v
        WHERE v.session_id = p_session_id AND v.lead_id = l.id AND NOT (coalesce((l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours'), false) AND v.visited_at <= now() - interval '4 hours')
          AND NOT (l.status = 'callback_scheduled' AND l.callback_scheduled_at IS NOT NULL AND l.callback_scheduled_at > v.visited_at AND l.callback_scheduled_at <= now())
          AND NOT EXISTS (SELECT 1 FROM public.legal_call_records c WHERE c.lead_id = l.id
            AND c.direction = 'inbound' AND c.created_at > v.visited_at))
    ORDER BY CASE WHEN (l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours') THEN 1 ELSE 0 END, CASE WHEN (l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours') THEN worked.last_dial_today END, l.created_at DESC, l.id
    LIMIT 1 FOR UPDATE OF l SKIP LOCKED;
  END IF;

  IF chosen IS NULL THEN RETURN NULL; END IF;
  -- All claim/renew paths lock the lead first, so expired reservations can be
  -- reclaimed without racing another caller's renewal.
  DELETE FROM public.legal_sales_lead_claims WHERE lead_id = chosen;
  INSERT INTO public.legal_sales_lead_claims(lead_id, session_id, expires_at)
    VALUES (chosen, p_session_id, now() + interval '15 minutes');
  UPDATE public.legal_client_leads SET rep_id = rep WHERE id = chosen;
  RETURN chosen;
END $function$;
