CREATE OR REPLACE FUNCTION public.legal_import_verified_legal_spend(p_from date, p_to date, p_account text, p_campaigns text[], p_rows jsonb, p_account_name text, p_total numeric, p_fetched_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE closed_through date := least(p_to,(now() AT TIME ZONE 'Australia/Sydney')::date-1);
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service only'; END IF;
 IF p_account IS DISTINCT FROM 'act_3333812883673737' THEN RAISE EXCEPTION 'Invalid source account'; END IF;
 PERFORM legal_replace_legal_meta_spend_with_metrics(p_from,p_to,p_account,p_campaigns,p_rows,p_account_name,p_total,p_fetched_at);
 UPDATE legal_ad_spend_sync_state SET
 reference_total=(SELECT coalesce(sum(r.spend_aud),0) FROM jsonb_to_recordset(p_rows) AS r(date date,spend_aud numeric) WHERE r.date<=closed_through),
 last_message='Meta via Windsor.ai; exact campaign reconciliation through '||closed_through||CASE WHEN p_to>closed_through THEN '; today provisional' ELSE '' END WHERE id=1;
END $function$;
