BEGIN
 INSERT INTO public.legal_firm_locations(firm_id,name,address,city,state,parking_info,nearby_landmarks)
 VALUES(NEW.id,coalesce(nullif(trim(NEW.city),''),'Main office'),NEW.address,NEW.city,NEW.state,NEW.parking_info,NEW.nearby_landmarks);
 RETURN NEW;
