 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT p IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.legal_phone_suppressions s
    WHERE s.phone_e164 = p OR (s.phone_tail <> '' AND s.phone_tail = public.legal_normalize_phone(p))
  );
$function$;
