$function$;
CREATE OR REPLACE FUNCTION public.legal_is_service_or_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE claim_role text;
DECLARE active_role text;
BEGIN
  BEGIN
    claim_role := coalesce(current_setting('request.jwt.claims', true)::json->>'role', '');
  EXCEPTION WHEN others THEN claim_role := '';
  END;
  IF claim_role = 'service_role' THEN RETURN true; END IF;

  -- NOTE: current_user is the function owner inside SECURITY DEFINER, so it must
  -- never be used for caller identity. current_setting('role') reflects the role
  -- PostgREST switched to for this request; session_user covers direct psql use.
  BEGIN
    active_role := coalesce(current_setting('role', true), '');
  EXCEPTION WHEN others THEN active_role := '';
  END;
  IF active_role IN ('service_role', 'postgres', 'supabase_admin') THEN RETURN true; END IF;
  IF active_role IN ('none', '') AND session_user IN ('postgres', 'supabase_admin') THEN RETURN true; END IF;

  RETURN public.legal_is_admin_user();
END;
$function$;
CREATE OR REPLACE FUNCTION public.legal_legal_calendar_history_fields(kind text, r jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE keys text[]; result jsonb;
BEGIN
 IF r IS NULL THEN RETURN NULL; END IF;
 keys:=CASE kind WHEN 'block' THEN ARRAY['date','start_time','end_time','is_recurring','recur_pattern','recur_day_of_week','recur_days_of_week','recur_day_of_month','recur_nth_week','recur_until','excluded_dates']
 WHEN 'hours' THEN ARRAY['override_date','override_type','start_time','end_time']
 WHEN 'weekly_hours' THEN ARRAY['day_of_week','open_time','close_time','is_open','slot_times','consult_duration_mins']
 WHEN 'settings' THEN ARRAY['consultation_duration_minutes','buffer_minutes']
 ELSE ARRAY['appointment_date','appointment_time','consultation_duration_minutes','status','outcome','disqualified_at'] END;
 SELECT jsonb_object_agg(key,value) INTO result FROM jsonb_each(r) WHERE key=ANY(keys);
 IF kind='weekly_hours' THEN result:=result||jsonb_build_object('is_closed',NOT (r->>'is_open')::boolean); END IF;
 IF kind='appointment' THEN result:=result||jsonb_build_object('calendar_status',CASE WHEN r->>'disqualified_at' IS NOT NULL OR r->>'outcome'='disqualified' THEN 'disqualified' WHEN r->>'status'='cancelled' THEN 'cancelled' ELSE 'booked' END); END IF;
 RETURN result;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_list_staff_portal_access()
 RETURNS TABLE(id uuid, user_id uuid, name text, email text, role text, is_active boolean, pages text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.legal_is_admin_user() THEN RAISE EXCEPTION 'Admins only'; END IF;
  RETURN QUERY SELECT r.id, r.user_id, r.name, r.email, r.role, r.is_active, public.legal_staff_portal_pages(r.id)
    FROM public.legal_sales_reps r ORDER BY r.name NULLS LAST, r.id;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_lock_legal_schedule_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE fid uuid;
BEGIN
 IF TG_TABLE_NAME='legal_firms' THEN fid:=NEW.id;
 ELSE
  fid:=CASE WHEN TG_OP='DELETE' THEN OLD.firm_id ELSE NEW.firm_id END;
  IF TG_OP='UPDATE' AND NEW.firm_id IS DISTINCT FROM OLD.firm_id THEN RAISE EXCEPTION 'Calendar rows cannot move between firms'; END IF;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(fid::text,0));
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_match_firm_application(p_phone text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ SELECT CASE WHEN count(*)=1 THEN (array_agg(id))[1] END FROM public.legal_firm_applications WHERE public.legal_firm_phone_key(phone)=public.legal_firm_phone_key(p_phone); $function$;
CREATE OR REPLACE FUNCTION public.legal_mirror_firm_sms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE app_id uuid; BEGIN app_id:=public.legal_match_firm_application(NEW.phone); IF app_id IS NOT NULL AND length(coalesce(NEW.body,''))>=1 THEN
IF TG_OP='UPDATE' THEN PERFORM public.legal_update_firm_sms_status(NULL,NEW.twilio_sid,NEW.delivery_status,NULL); RETURN NEW; END IF;
INSERT INTO public.legal_firm_application_messages(application_id,direction,phone,body,status,twilio_sid,source_sms_id,created_at,reviewed_at) VALUES(app_id,NEW.direction,public.legal_firm_phone_key(NEW.phone),NEW.body,coalesce(NEW.delivery_status,'unknown'),NEW.twilio_sid,NEW.id,NEW.created_at,CASE WHEN TG_OP='INSERT' THEN NULL ELSE now() END) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $function$;
CREATE OR REPLACE FUNCTION public.legal_normalize_phone(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT right(regexp_replace(coalesce(p,''), '\D', '', 'g'), 9);
$function$;

RESET check_function_bodies;
